<script>const choice=document.getElementById('rw-kind');choice.addEventListener('change',()=>{document.getElementById('rw-save').textContent=choice.value==='same_part'?'Publish shared identity':'Save agreed decision';for(const n of ['ret_verified','am_verified','current_specification_verified'])document.querySelector('[name="'+n+'"]').required=choice.value==='same_part';document.getElementById('rw-confirm-part').required=choice.value==='same_part';const followup=choice.value!==''&&!['same_part','not_match'].includes(choice.value);document.getElementById('rw-owner').required=followup;document.getElementById('rw-due').required=followup;});choice.value=<?=json_encode((string)($_POST['decision']??''), JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;choice.dispatchEvent(new Event('change'));</script>
