<script>
document.querySelectorAll('.rw-prepare').forEach(button=>button.addEventListener('click',()=>{
 const note=document.getElementById('rw-note');
 if(note.value.trim() && !window.confirm('Replace the unsaved note and item selections with this suggested review?'))return;
 document.querySelectorAll('[name="asset_ids[]"]').forEach(el=>el.checked=el.value===button.dataset.asset);
 for(const n of ['ret_verified','am_verified','current_specification_verified'])document.querySelector('[name="'+n+'"]').checked=false;
 choice.value=button.dataset.decision;choice.dispatchEvent(new Event('change'));note.value=button.dataset.note;
 const status=document.getElementById('rw-prepared');status.textContent='Draft prepared. Nothing has been saved. Check the evidence together, replace the draft with your findings, and complete the required confirmations before saving.';status.focus();status.scrollIntoView({behavior:'smooth',block:'center'});
}));
</script>

<script>
// Browsing is not a save. Confirm before discarding a review that has been edited.
const reviewForm=document.getElementById('rw-decision');let reviewDirty=false;
reviewForm.addEventListener('input',()=>reviewDirty=true);reviewForm.addEventListener('change',()=>reviewDirty=true);
document.querySelectorAll('.rw-prepare').forEach(b=>b.addEventListener('click',()=>reviewDirty=true));
const canLeave=()=>!reviewDirty||window.confirm('This review has unsaved selections or notes. Leave without saving? Uploaded photos are already saved.');
document.querySelectorAll('.rw-leave').forEach(a=>a.addEventListener('click',e=>{if(!canLeave())e.preventDefault();}));
document.querySelectorAll('.rw-navigation').forEach(f=>f.addEventListener('submit',e=>{if(!canLeave())e.preventDefault();}));
</script>

<script>
const comparison=document.getElementById('rw-comparison');
function updateComparison(){
 comparison.replaceChildren();
 const selected=[...document.querySelectorAll('[name="asset_ids[]"]:checked')];
 if(!selected.length)comparison.textContent='Select an AM item above to compare its original description here.';
 for(const item of selected){const p=document.createElement('p');p.textContent=item.dataset.name+' ('+item.dataset.tag+'): '+item.dataset.original;comparison.append(p);if(item.dataset.block){const warning=document.createElement('p');warning.className='alert alert-danger';warning.textContent='Cannot publish as the same part: '+item.dataset.block;comparison.append(warning);}}
 document.getElementById('rw-save').disabled=choice.value==='same_part'&&(!selected.length||selected.some(x=>x.dataset.block));
}
document.querySelectorAll('[name="asset_ids[]"]').forEach(el=>el.addEventListener('change',()=>{document.getElementById('rw-confirm-part').value='';for(const n of ['ret_verified','am_verified','current_specification_verified'])document.querySelector('[name="'+n+'"]').checked=false;updateComparison();}));
choice.addEventListener('change',updateComparison);
document.querySelectorAll('.rw-prepare').forEach(b=>b.addEventListener('click',()=>{document.getElementById('rw-confirm-part').value='';updateComparison();}));
document.getElementById('rw-start-question')?.addEventListener('click',e=>{const b=e.currentTarget,note=document.getElementById('rw-note');if(note.value.trim()&&!confirm('Replace your unsaved note with this question?'))return;note.value=b.dataset.note;choice.value=b.dataset.decision;choice.dispatchEvent(new Event('change'));reviewDirty=true;note.focus();note.scrollIntoView({behavior:'smooth',block:'center'});});
updateComparison();
</script>
